class Solution {
public:
    int maxScore(vector<string>& cards, char x) {
        int z = 0;
        array<int,26> L{}, R{};
        int s = 0;
        for (auto& c : cards) {
            if (c[0] == x && c[1] == x) z++;
            else if (c[0] == x) { L[c[1]-'a']++; s++; }
            else if (c[1] == x) { R[c[0]-'a']++; s++; }
        }
        int mx = 0;
        for (int c = 0; c < 26; c++) mx = max(mx, L[c] + R[c]);
        int ms = min(s / 2, s - mx);
        int rs = s - 2 * ms;
        return ms + min(rs, z) + max(z - rs, 0) / 2;
    }
};

