class Solution {
    public int maxScore(String[] cards, char x) {
        int z = 0, s = 0;
        int[] L = new int[26], R = new int[26];
        for (String c : cards) {
            if (c.charAt(0) == x && c.charAt(1) == x) z++;
            else if (c.charAt(0) == x) { L[c.charAt(1) - 'a']++; s++; }
            else if (c.charAt(1) == x) { R[c.charAt(0) - 'a']++; s++; }
        }
        int mx = 0;
        for (int c = 0; c < 26; c++) mx = Math.max(mx, L[c] + R[c]);
        int ms = Math.min(s / 2, s - mx);
        int rs = s - 2 * ms;
        return ms + Math.min(rs, z) + Math.max(z - rs, 0) / 2;
    }
}

