var maxScore = function(cards, x) {
    let z = 0, s = 0;
    const L = Array(26).fill(0), R = Array(26).fill(0);
    for (const c of cards) {
        if (c[0] === x && c[1] === x) z++;
        else if (c[0] === x) { L[c.charCodeAt(1) - 97]++; s++; }
        else if (c[1] === x) { R[c.charCodeAt(0) - 97]++; s++; }
    }
    let mx = 0;
    for (let c = 0; c < 26; c++) mx = Math.max(mx, L[c] + R[c]);
    const ms = Math.min(Math.floor(s / 2), s - mx);
    const rs = s - 2 * ms;
    return ms + Math.min(rs, z) + Math.floor(Math.max(z - rs, 0) / 2);
};
